//! What each comparison option does, for the "About this option" card of the Compare windows.

/// The description of a schema option, by its name.
pub fn schema(name: &str) -> &'static str {
    match name {
        "AddDatabaseUseStatement" => "Starts the deployment script with USE [target database], so the script runs in the right database wherever it is opened.",
        "ObjectExistenceChecks" => "Wraps each CREATE and DROP in a check that the object does or does not exist yet, so the script can run against a database that has changed since the comparison.",
        "AddWithEncryption" => "Creates and alters stored procedures, functions, views and triggers WITH ENCRYPTION, so their text cannot be read in the target.",
        "NoAutoColumnMapping" => "When on, columns of mapped tables whose names differ only a little (case, spaces, underscores) are paired automatically. Turn it off to pair columns by exact name only.",
        "ConsiderNextFilegroupInPartitionSchemes" => "Compares the filegroup marked NEXT USED of partition schemes too; otherwise schemes that differ only in it are identical.",
        "SsdtCompatibleOptions" => "Reads and writes scripts folders in the layout of a Visual Studio database project (SSDT) instead of SQL Compare's.",
        "DecryptPost2kEncryptedObjects" => "Reads the text of encrypted modules so they can be compared and deployed. Needs a connection that may use the dedicated administrator connection or sysadmin rights.",
        "DisableAndReenableDdlTriggers" => "Disables the target's database DDL triggers while the script runs and enables them again at the end, so they do not block or log the deployment.",
        "NoErrorHandling" => "Leaves out the checks after each batch that stop the script and roll back when a statement fails.",
        "DoNotOutputCommentHeader" => "Leaves out the comment block at the top of the script that names the source, the target and when it was made.",
        "UseClrUdtToStringForClrMigration" => "Changes CLR assemblies by dropping and creating them, converting CLR type columns through their string form, instead of ALTER ASSEMBLY.",
        "NoTransactions" => "Runs the script without BEGIN TRANSACTION and COMMIT: a failure part way leaves the changes made so far in place.",
        "NoDeploymentLogging" => "Records each deployment in a log table in the target database.",
        "ForceColumnOrder" => "Treats tables whose columns are in a different order as different, and rebuilds the target table to put new columns in the source's order instead of adding them at the end.",
        "IgnoreMigrationScripts" => "Ignores the migration scripts of a source control project, so changes are scripted as a plain comparison would.",
        "CaseSensitiveObjectDefinition" => "Compares object names and definitions case-sensitively, so objects whose names differ only in case are different objects.",
        "UseCompatibilityLevel" => "Parses scripts with the database's compatibility level rather than the server version, so keywords of newer versions are read as names.",
        "DropAndCreateInsteadOfAlter" => "Changes modules by dropping and creating them, with existence checks, so the script can be run again.",
        "CreateOrAlterInsteadOfAlter" => "Uses CREATE OR ALTER for modules where the server supports it, so the script can be run again.",
        "AddNoPopulation" => "Creates full-text indexes WITH NO POPULATION, so the index is not filled while the script runs.",
        "AddOnlineOn" => "Creates indexes and alters columns WITH (ONLINE = ON), keeping the table usable during the change on editions that support it.",
        "IgnoreSchemaObjectAuthorization" => "Ignores who owns schema-bound objects (ALTER AUTHORIZATION).",
        "IgnoreBindings" => "Ignores rules and defaults bound to columns and user-defined types.",
        "IgnoreCertificatesAndCryptoKeys" => "Leaves certificates, symmetric keys and asymmetric keys out of the comparison.",
        "IgnoreChangeTracking" => "Ignores whether change tracking is on for tables.",
        "IgnoreChecks" => "Ignores check constraints on tables.",
        "IgnoreCollations" => "Ignores the collation of columns, so columns that differ only in collation are identical.",
        "IgnoreComments" => "Ignores comments in the text of views, procedures, functions and triggers.",
        "IgnoreConstraintNames" => "Compares indexes and constraints by what they do, not by their names; renamed constraints are identical.",
        "IgnoreDataCompression" => "Ignores the data compression of tables and indexes.",
        "IgnoreDatabaseAndServerName" => "Ignores the server and database parts of the names synonyms point to.",
        "IgnoreTriggerOrder" => "Ignores the first and last firing order set on DML triggers.",
        "IgnoreTriggers" => "Leaves DML triggers out of the comparison.",
        "IgnoreQueueEventNotifications" => "Ignores event notifications defined on Service Broker queues.",
        "IgnoreExtendedProperties" => "Ignores extended properties on every object.",
        "IgnoreFileGroups" => "Ignores the filegroups, partition schemes and partition functions that tables and indexes are stored on.",
        "IgnoreFillFactor" => "Ignores the fill factor and PAD_INDEX of indexes.",
        "IgnoreKeys" => "Leaves foreign keys out of the comparison.",
        "IgnoreFullTextIndexing" => "Leaves full-text catalogs and full-text indexes out of the comparison.",
        "IgnoreIdentityProperties" => "Ignores whether columns are IDENTITY columns.",
        "IgnoreIdentitySeedAndIncrement" => "Ignores the seed and increment of IDENTITY columns; the column is still compared as an identity.",
        "IgnoreIndexes" => "Leaves indexes, primary keys and unique constraints out of the comparison.",
        "IgnoreInsteadOfTriggers" => "Leaves INSTEAD OF triggers out of the comparison.",
        "IgnoreIndexLockProperties" => "Ignores ALLOW_ROW_LOCKS and ALLOW_PAGE_LOCKS of indexes.",
        "IgnoreNocheckAndWithNocheck" => "Ignores whether foreign keys and check constraints are disabled (NOCHECK) or were created WITH NOCHECK.",
        "IgnoreNotForReplication" => "Ignores the NOT FOR REPLICATION setting of constraints, triggers and identity columns.",
        "IgnoreNullability" => "Ignores whether columns allow NULL.",
        "IgnorePerformanceIndexes" => "Leaves out indexes that are not primary keys or unique, which only make queries faster.",
        "IgnorePermissions" => "Ignores GRANT, DENY and REVOKE on objects, schemas and the database.",
        "IgnoreReplicationTriggers" => "Leaves out triggers created by replication.",
        "IgnoreQuotedIdentifiersAndAnsiNullSettings" => "Ignores the QUOTED_IDENTIFIER and ANSI_NULLS settings modules were created with.",
        "IgnoreSensitivityClassification" => "Ignores the sensitivity labels of columns.",
        "IgnoreSquareBrackets" => "Ignores square brackets around names in the text of modules.",
        "IgnoreStatistics" => "Leaves user-created statistics out of the comparison.",
        "IgnoreStatisticsNorecompute" => "Ignores STATISTICS_NORECOMPUTE of indexes.",
        "IgnoreSystemNamedConstraintNames" => "Ignores the names SQL Server generated for unnamed constraints and indexes, which differ in every database.",
        "IgnoreTSQLT" => "Leaves the tSQLt framework and the test classes it created out of the comparison.",
        "IgnoreUserProperties" => "Ignores properties of users such as their login and default schema; the user itself is still compared.",
        "IgnoreUsers" => "Ignores the permissions and role memberships of users.",
        "IgnoreWhiteSpace" => "Ignores spaces, tabs and line breaks in the text of modules, so code that differs only in layout is identical.",
        "IgnoreWithElementOrder" => "Ignores the order of the items in WITH clauses of modules.",
        "IgnoreWithEncryption" => "Ignores whether modules are encrypted.",
        "IgnoreWithNocheck" => "Ignores whether foreign keys and check constraints were created WITH NOCHECK.",
        "IgnoreDynamicDataMasking" => "Ignores masking functions on columns.",
        "IgnoreStatisticsIncremental" => "Ignores STATISTICS_INCREMENTAL of indexes and statistics.",
        "IncludeDependencies" => "Deploys the objects the selected objects need along with them.",
        _ => "",
    }
}

/// The description of a data option, by its name.
pub fn data(name: &str) -> &'static str {
    match name {
        "IgnoreSpaces" => "Pairs tables and columns whose names differ only in spaces.",
        "IgnoreUnderscores" => "Pairs tables and columns whose names differ only in underscores.",
        "IncludeIdentities" => "Compares and deploys identity columns; the script turns IDENTITY_INSERT on where it inserts them.",
        "IncludeTimestamps" => "Compares timestamp (rowversion) columns. They cannot be deployed, so differences in them alone are not deployed.",
        "IncludeViews" => "Lists views next to tables, so indexed views and views with a key can be compared.",
        "CaseSensitiveObjectDefinition" => "Pairs tables and columns by case-sensitive names.",
        "IncludeGeneratedAlwaysColumns" => "Compares GENERATED ALWAYS columns of temporal and ledger tables. They are never deployed.",
        "CompressTemporaryFiles" => "Compresses the files the comparison keeps the rows in, using less disk for slower comparisons.",
        "ForceBinaryCollation" => "Compares text with a binary collation, so values that differ only in case or accents are different.",
        "IncludeIdenticalRecords" => "Keeps identical rows in the results, so they can be viewed and exported. Comparisons use more disk.",
        "TreatEmptyStringAsNull" => "Treats empty strings and NULL as the same value.",
        "TrimTrailingSpaces" => "Ignores spaces at the end of text values.",
        "UseChecksumComparison" => "Compares a checksum of each table first and reads the rows only of tables whose checksums differ. Faster for large identical tables; rows are not kept.",
        "UseFullPrecisionForComparison" => "Compares float and real values at full precision instead of as they are shown.",
        "DisableDdlTriggers" => "Disables DDL triggers while the script runs and enables them again afterwards.",
        "DisableTriggers" => "Disables the DML triggers of the tables changed while the script runs, so they do not fire for the deployed rows.",
        "DisableKeys" => "Disables foreign keys while rows are deployed and enables them again at the end, so rows can go in any order.",
        "DontOutputComments" => "Leaves the comments that name each table out of the script.",
        "DontUseTransactions" => "Runs the script without a transaction: a failure part way leaves the rows deployed so far in place.",
        "DropConstraintsAndIndexes" => "Drops primary keys, indexes and unique constraints before deploying rows and creates them again afterwards. Can be faster for many rows.",
        "AddDatabaseUseStatement" => "Starts the deployment script with USE [target database].",
        "OutputCommentHeader" => "Puts a comment block at the top of the script that names the source, the target and when it was made.",
        "ReseedIdentity" => "Resets the identity seed of the tables changed to the largest value deployed.",
        "SkipFkChecks" => "Enables foreign keys again WITH NOCHECK, so the existing rows are not checked against them.",
        "TransportClrBinary" => "Deploys CLR type values as binary rather than as their string form.",
        _ => "",
    }
}
